def job_list(request, client_id, project_name):
    """
    get job list of project from one client
    :param request: request object
    :param client_id: client id
    :param project_name: project name
    :return: list of jobs
    """
    if request.method == 'GET':
        client = Client.objects.get(id=client_id)
        scrapyd = get_scrapyd(client)
        try:
            result = scrapyd.list_jobs(project_name)
            jobs = []
            statuses = ['pending', 'running', 'finished']
            for status in statuses:
                for job in result.get(status):
                    job['status'] = status
                    jobs.append(job)
            return JsonResponse(jobs)
        except ConnectionError:
            return JsonResponse({'message': 'Connect Error'}, status=500)

def get_charset(self, default: str) -> str:
    """Returns charset parameter from Content-Type header or default."""
    ctype = self.headers.get(CONTENT_TYPE, "")
    mimetype = parse_mimetype(ctype)
    return mimetype.parameters.get("charset", default)

def write_data_table(self, report, report_data, has_totals=True):
    self.data.append([c["title"] for c in report.schema])
    for datum in report_data:
        datum = report.read_datum(datum)
        self.data.append([format_data(data, format_iso_dates=True) for data in datum])

    if has_totals:
        for datum in report.get_totals(report_data):
            datum = report.read_datum(datum)
            self.data.append([format_data(data) for data in datum])

