async def open_code_folder(request: FolderRequest):
    """
    Opens code folder.

    :param request: The HTTP request object.
    :return: A JSON response with the status of the operation.
    """

    try:
        if request.discussion_id:
            discussion_id = request.discussion_id

            ASCIIColors.info("Opening folder:")
            # Create a temporary file.
            root_folder = lollmsElfServer.lollms_paths.personal_outputs_path / "discussions" / f"d_{discussion_id}"
            root_folder.mkdir(parents=True, exist_ok=True)
            if platform.system() == 'Windows':
                subprocess.run(['start', str(root_folder)], check=True, shell=True)
            elif platform.system() == 'Linux':
                subprocess.run(['xdg-open', str(root_folder)], check=True)
            elif platform.system() == 'Darwin':
                subprocess.run(['open', str(root_folder)], check=True)
            return {"status": True, "execution_time": 0}
        elif request.folder_path:
            folder_path = os.path.realpath(request.folder_path)
            # Verify that this is a file and not an executable
            root_folder = Path(folder_path)
            is_valid_folder_path = root_folder.is_dir()

            if not is_valid_folder_path:
                return {"status":False, "error":"Invalid folder path"}

            ASCIIColors.info("Opening folder:")
            # Create a temporary file.
            root_folder.mkdir(parents=True, exist_ok=True)
            if platform.system() == 'Windows':
                subprocess.run(['start', str(root_folder)], check=True, shell=True)
            elif platform.system() == 'Linux':
                subprocess.run(['xdg-open', str(root_folder)], check=True)
            elif platform.system() == 'Darwin':
                subprocess.run(['open', str(root_folder)], check=True)
            return {"status": True, "execution_time": 0}

    except Exception as ex:
        trace_exception(ex)

def create_user(
    user_name: str,
    password: Optional[str] = None,
) -> None:
    """Create a new user.

    Args:
        user_name: The name of the user to create.
        password: The password of the user to create.
    """
    client = Client()
    if not password:
        if client.zen_store.type != StoreType.REST:
            password = click.prompt(
                f"Password for user {user_name}",
                hide_input=True,
            )
        else:
            password = click.prompt(
                f"Password for user {user_name}. Leave empty to generate an "
                f"activation token",
                default="",
                hide_input=True,
            )

    try:
        new_user = client.create_user(name=user_name, password=password)

        cli_utils.declare(f"Created user '{new_user.name}'.")
    except EntityExistsError as err:
        cli_utils.error(str(err))
    else:
        if not new_user.active and new_user.activation_token is not None:
            cli_utils.declare(
                f"The created user account is currently inactive. You can "
                f"activate it by visiting the dashboard at the following URL:\n"
                f"{client.zen_store.url}/signup?user={str(new_user.id)}&username={new_user.name}&token={new_user.activation_token}\n"
            )

