def test_creating_users_in_parallel_do_not_duplicate_fails(
    clean_client: "Client",
):
    """Tests creating a user with an existing username fails in parallel mode."""

    def silent_create_user(user_request: UserRequest):
        """This function attempts to create a user and silently passes
        if a duplicate user exists. This is used to simulate race
        conditions in parallel user creation.
        """
        try:
            clean_client.zen_store.create_user(user_request)
        except EntityExistsError:
            pass

    user_name = "test_user"
    password = "P@ssw0rd"
    count = 100

    threads: List[Thread] = []
    for _ in range(count):
        t = Thread(
            target=silent_create_user,
            args=(UserRequest(name=user_name, password=password),),
        )
        threads.append(t)
    for t in threads:
        t.start()
    for t in threads:
        t.join()

    users = clean_client.zen_store.list_users(
        user_filter_model=UserFilter(name=user_name)
    )
    assert users.total == 1

def applyAttributes(mjml_element):
    if len(mjml_element) == 0:
        return {}
    def parse(_mjml, parentMjClass='', *, template_dir):
        tagName = _mjml.name
        is_comment = not isinstance(tagName, str)
        if is_comment:
            # XML comment: <cyfunction Comment at 0x…>
            # (this needs to be extended when "keepComments" should be implemented)
            return None
        attributes = _mjml.attrs
        children = [child for child in _mjml]
        classes = ignore_empty(attributes.get('mj-class', '').split(' '))

        # upstream parses text contents (+ comments) in mjml-parser-xml/index.js
        content = _mjml.decode_contents()

        attributesClasses = {}
        for css_class in classes:
            mjClassValues = globalDatas.classes.get(css_class)
            if mjClassValues:
                attributesClasses.update(mjClassValues)

        parent_mj_classes = ignore_empty(parentMjClass.split(' '))
        def default_attr_classes(value):
            return globalDatas.classesDefault.get(value, {}).get(tagName, {})
        defaultAttributesForClasses = merge_dicts(*map(default_attr_classes, parent_mj_classes))
