def cast(self, typ, value):
    """
    cast value to given format.
    """
    if typ == "int":
        return int(value)

    elif typ == "float":
        return float(value)

    elif typ == "str":
        return "" if value is None else str(value)

    elif typ == "bytes":
        return b"" if value is None else bytes(value)

    elif typ == "bool":
        value = "" if value is None else str(value)
        return value.lower() in ("1", "true", "on", "yes", "y")

    elif typ == "time":
        value = "" if value is None else str(value)
        if not value:
            value = "0:00"
        if ":" not in value:
            value += ":00"
        return value

    elif typ in ("file", "folder"):
        return "" if value in (None, "") else os.path.realpath(os.path.expanduser(os.fsdecode(value)))

    else:
        return value

def cast(self, typ, value):
    """
    cast value to given format.
    """
    if typ == "int":
        return int(value)

    elif typ == "float":
        return float(value)

    elif typ == "str":
        return "" if value is None else str(value)

    elif typ == "bytes":
        return b"" if value is None else bytes(value)

    elif typ == "bool":
        value = "" if value is None else str(value)
        return value.lower() in ("1", "true", "on", "yes", "y")

    elif typ == "time":
        default_value = "0:00"
        value = "" if value is None else str(value)
        if not value:
            value = default_value
        elif ":" not in value:
            value += ":00"

        hours, seconds = value.split(":", 1)
        if (
            hours.isnumeric()
            and seconds.isnumeric()
            and 0 <= int(hours) <= 23
            and 0 <= int(seconds) <= 59
        ):
            pass
        else:
            value = default_value

        return value

    elif typ in ("file", "folder"):
        return (
            ""
            if value in (None, "")
            else os.path.realpath(os.path.expanduser(os.fsdecode(value)))
        )

    else:
        return value

def signup(request):
    if not settings.REGISTRATION_OPEN:
        return HttpResponseForbidden()

    ctx = {}
    form = forms.SignupForm(request.POST)
    if form.is_valid():
        email = form.cleaned_data["identity"]
        tz = form.cleaned_data["tz"]
        user = _make_user(email, tz)
        profile = Profile.objects.for_user(user)
        profile.send_instant_login_link()
        ctx["created"] = True
    else:
        ctx = {"form": form}

    response = render(request, "accounts/signup_result.html", ctx)
    if ctx.get("created"):
        response.set_cookie("auto-login", "1", max_age=300, httponly=True)

    return response

