def get_multi(self, keys, server_key):
    """
    Gets multiple values from memcache for the given keys.

    :param keys: keys for values to be retrieved from memcache
    :param servery_key: key to use in determining which server in the ring
                        is used
    :returns: list of values
    """
    server_key = md5hash(server_key)
    keys = [md5hash(key) for key in keys]
    for (server, fp, sock) in self._get_conns(server_key):
        try:
            sock.sendall('get %s\r\n' % ' '.join(keys))
            line = fp.readline().strip().split()
            responses = {}
            while line[0].upper() != 'END':
                if line[0].upper() == 'VALUE':
                    size = int(line[3])
                    value = fp.read(size)
                    if int(line[2]) & PICKLE_FLAG:
                        value = pickle.loads(value)
                    responses[line[1]] = value
                    fp.readline()
                line = fp.readline().strip().split()
            values = []
            for key in keys:
                if key in responses:
                    values.append(responses[key])
                else:
                    values.append(None)
            self._return_conn(server, fp, sock)
            return values
        except Exception, e:
            self._exception_occurred(server, e)

def get_multi(self, keys, server_key):
    """
    Gets multiple values from memcache for the given keys.

    :param keys: keys for values to be retrieved from memcache
    :param servery_key: key to use in determining which server in the ring
                        is used
    :returns: list of values
    """
    server_key = md5hash(server_key)
    keys = [md5hash(key) for key in keys]
    for (server, fp, sock) in self._get_conns(server_key):
        try:
            sock.sendall('get %s\r\n' % ' '.join(keys))
            line = fp.readline().strip().split()
            responses = {}
            while line[0].upper() != 'END':
                if line[0].upper() == 'VALUE':
                    size = int(line[3])
                    value = fp.read(size)
                    if int(line[2]) & PICKLE_FLAG:
                        if self._allow_unpickle:
                            value = pickle.loads(value)
                        else:
                            value = None
                    elif int(line[2]) & JSON_FLAG:
                        value = json.loads(value)
                    responses[line[1]] = value
                    fp.readline()
                line = fp.readline().strip().split()
            values = []
            for key in keys:
                if key in responses:
                    values.append(responses[key])
                else:
                    values.append(None)
            self._return_conn(server, fp, sock)
            return values
        except Exception, e:
            self._exception_occurred(server, e)

def CreateAuthenticator():
    """Create a packet autenticator. All RADIUS packets contain a sixteen
    byte authenticator which is used to authenticate replies from the
    RADIUS server and in the password hiding algorithm. This function
    returns a suitable random string that can be used as an authenticator.

    :return: valid packet authenticator
    :rtype: binary string
    """

    data = []
    for i in range(16):
        data.append(random.randrange(0, 256))
    if six.PY3:
        return bytes(data)
    else:
        return ''.join(chr(b) for b in data)

