def is_whitelisted(self, method):
	fn = getattr(self, method, None)
	if not fn:
		raise NotFound("Method {0} not found".format(method))
	elif not getattr(fn, "whitelisted", False):
		raise Forbidden("Method {0} not whitelisted".format(method))

