def to_plist(self, data, options=None):
    """
    Given some Python data, produces binary plist output.
    """
    options = options or {}

    if biplist is None:
        raise ImproperlyConfigured("Usage of the plist aspects requires biplist.")

    return biplist.writePlistToString(self.to_simple(data, options))

def to_yaml(self, data, options=None):
    """
    Given some Python data, produces YAML output.
    """
    options = options or {}

    if yaml is None:
        raise ImproperlyConfigured("Usage of the YAML aspects requires yaml.")

    return yaml.dump(self.to_simple(data, options))

def get(self, key):
    """
    Gets the object specified by key.  It will also unserialize the object
    before returning if it is serialized in memcache with JSON, or if it
    is pickled and unpickling is allowed.

    :param key: key
    :returns: value of the key in memcache
    """
    key = md5hash(key)
    value = None
    for (server, fp, sock) in self._get_conns(key):
        try:
            sock.sendall('get %s\r\n' % key)
            line = fp.readline().strip().split()
            while line[0].upper() != 'END':
                if line[0].upper() == 'VALUE' and line[1] == key:
                    size = int(line[3])
                    value = fp.read(size)
                    if int(line[2]) & PICKLE_FLAG:
                        if self._allow_unpickle:
                            value = pickle.loads(value)
                        else:
                            value = None
                    elif int(line[2]) & JSON_FLAG:
                        value = json.loads(value)
                    fp.readline()
                line = fp.readline().strip().split()
            self._return_conn(server, fp, sock)
            return value
        except Exception, e:
            self._exception_occurred(server, e)

