def _fill(self, target=1, more=None, untilend=False):
    if more:
        target = len(self._buf) + more
    while untilend or (len(self._buf) < target):
        # crutch to enable HttpRequest.from_bytes
        if self._sock is None:
            chunk = b""
        else:
            chunk = self._sock.recv(8 << 10)
        # print('!!! recv', chunk)
        if not chunk:
            self._end = True
            if untilend:
                return
            else:
                raise EOFError
        self._buf += chunk

