def add(self, item: Model, raise_exception: bool = False) -> bool:
    try:
        self.session.add(item)
        self.session.commit()
        self.message = (as_unicode(self.add_row_message), "success")
        return True
    except IntegrityError as e:
        self.message = (as_unicode(self.add_integrity_error_message), "warning")
        log.warning(LOGMSG_WAR_DBI_ADD_INTEGRITY.format(str(e)))
        self.session.rollback()
        if raise_exception:
            raise e
        return False
    except Exception as e:
        self.message = (
            as_unicode(self.general_error_message + " " + str(sys.exc_info()[0])),
            "danger",
        )
        log.exception(LOGMSG_ERR_DBI_ADD_GENERIC.format(str(e)))
        self.session.rollback()
        if raise_exception:
            raise e
        return False

def multi_log(text, console=True, stderr=True,
              log=None, log_level=logging.DEBUG):
    if stderr:
        sys.stderr.write(text)
    if console:
        conpath = "/dev/console"
        if os.path.exists(conpath):
            with open(conpath, 'w') as wfh:
                wfh.write(text)
                wfh.flush()
        else:
            # A container may lack /dev/console (arguably a container bug).  If
            # it does not exist, then write output to stdout.  this will result
            # in duplicate stderr and stdout messages if stderr was True.
            #
            # even though upstart or systemd might have set up output to go to
            # /dev/console, the user may have configured elsewhere via
            # cloud-config 'output'.  If there is /dev/console, messages will
            # still get there.
            sys.stdout.write(text)
    if log:
        if text[-1] == "\n":
            log.log(log_level, text[:-1])
        else:
            log.log(log_level, text)

async def __send_notice(
    self, guild: discord.guild, user: Union[discord.Member, discord.User], event: str, *, message_format=None
) -> Optional[discord.Message]:
    """Sends the notice for the event."""

    format_str = message_format or await self.__get_random_message_format(guild, event)

    count = await self.config.guild(guild).get_attr(event).counter()
    plural = ""
    if count and count != 1:
        plural = "s"

    channel = await self.__get_channel(guild, event)

    role_str: str = ""
    if isinstance(user, discord.Member):
        roles = [r.name for r in user.roles if r.name != "@everyone"]
        if len(roles) > 0:
            role_str = humanize_list(roles)

    try:
        return await channel.send(
            format_str.format(member=user, server=guild, bot=user, count=count or "", plural=plural, roles=role_str)
        )
    except discord.Forbidden:
        log.error(
            f"Failed to send {event} message to channel ID {channel.id} (server ID {guild.id}): "
            "insufficient permissions"
        )
        return None
    except discord.DiscordException:
        log.error(f"Failed to send {event} message to channel ID {channel.id} (server ID {guild.id})")
        return None

