def assertXSS(self, response, status_code=200, msg_prefix=''):
    if status_code is not None:
        self.assertEqual(
            response.status_code, status_code,
            msg_prefix + "Couldn't retrieve content: Response code was %d"
            " (expected %d)" % (response.status_code, status_code)
        )

    xss = response.content.find(b"<") != -1 or response.content.find(b">") != -1
    self.assertFalse(xss, msg=msg_prefix+str(response.content))

def is_authenticated(session=flask.session):
    return session.get("name") and session.get(
        "authenticated"
    )  # NOTE: why checks name?

def wrapper(*args, **kwargs):
    s = flask.session
    #: already authenticated?
    if is_authenticated(s):
        perms = parse_permissions(s)
        if perm not in perms or not perms[perm]:
            response = "Forbidden", 403
        else:
            response = func(*args, **kwargs)

    else:
        clear_session(s)
        if flask.request.headers.get("X-Requested-With") == "XMLHttpRequest":
            response = "Forbidden", 403

        else:
            location = flask.url_for(
                "app.login",
                next=flask.request.url
            )
            response = flask.redirect(location)

    return response

