def TakeScreenShot(request):
    print "\n[INFO] Taking Screenshot"
    try:
        if request.method == 'POST':
            MD5=request.POST['md5']
            m=re.match('[0-9a-f]{32}',MD5)
            if m:
                data = {}
                r=random.randint(1, 1000000)
                DIR=settings.BASE_DIR
                SCRDIR=os.path.join(settings.UPLD_DIR, MD5+'/screenshots-apk/')#make sure that list only png from this directory
                TOOLSDIR=os.path.join(DIR, 'DynamicAnalyzer/tools/')  #TOOLS DIR
                adb=getADB(TOOLSDIR)
                subprocess.call([adb, "-s", getIdentifier() ,"shell", "screencap", "-p", "/data/local/screen.png"])
                subprocess.call([adb, "-s", getIdentifier() ,"pull", "/data/local/screen.png", SCRDIR + "screenshot-"+str(r)+".png"])
                print "\n[INFO] Screenshot Taken"
                data = {'screenshot': 'yes'}
                return HttpResponse(json.dumps(data), content_type='application/json') 
            else:
                return HttpResponseRedirect('/error/')
        else:
            return HttpResponseRedirect('/error/')
    except:
        PrintException("[ERROR] Taking Screenshot")
        return HttpResponseRedirect('/error/')

def Smali(request):
    try:
        m=re.match('[0-9a-f]{32}',request.GET['md5'])
        if m:
            MD5=request.GET['md5']
            SRC=os.path.join(settings.UPLD_DIR, MD5+'/smali_source/')
            html=''
            for dirName, subDir, files in os.walk(SRC):
                for jfile in files:
                    if jfile.endswith(".smali"):
                        file_path=os.path.join(SRC,dirName,jfile)
                        if "+" in jfile:
                            fp2=os.path.join(SRC,dirName,jfile.replace("+","x"))
                            shutil.move(file_path,fp2)
                            file_path=fp2
                        fileparam=file_path.replace(SRC,'')
                        html+="<tr><td><a href='../ViewSource/?file="+escape(fileparam)+"&md5="+MD5+"'>"+escape(fileparam)+"</a></td></tr>"
        context = {'title': 'Smali Source',
                    'files': html,
                    'md5': MD5,
                    }
        template="smali.html"
        return render(request,template,context)
    except:
        PrintException("[ERROR] Getting Smali Files")
        return HttpResponseRedirect('/error/')

def testzip(self) -> Optional[str]:
    self.fp.seek(self.afterheader)
    self.worker = Worker(self.files, self.afterheader, self.header, self.mp)
    for f in self.files:
        self.worker.register_filelike(f.id, None)
    try:
        self.worker.extract(self.fp, parallel=(not self.password_protected), skip_notarget=False)  # TODO: print progress
    except CrcError as crce:
        return crce.args[2]
    else:
        return None
